-- Ribbit Platform Full Initial Database Dump (Schema + Seed)
PRAGMA foreign_keys = OFF;
BEGIN TRANSACTION;

-- Ribbit Platform SQLite Database Schema

CREATE TABLE IF NOT EXISTS plans (
    plan_id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL UNIQUE,
    monthly_price REAL NOT NULL,
    max_profiles INTEGER NOT NULL DEFAULT 1
);

CREATE TABLE IF NOT EXISTS users (
    user_id INTEGER PRIMARY KEY AUTOINCREMENT,
    email TEXT NOT NULL UNIQUE,
    password_hash TEXT NOT NULL,
    spotify_id TEXT UNIQUE,
    spotify_premium INTEGER NOT NULL DEFAULT 0,
    spotify_access_token TEXT,
    spotify_refresh_token TEXT,
    spotify_token_expires_at TEXT,
    display_name TEXT NOT NULL,
    age INTEGER,
    plan_id INTEGER NOT NULL REFERENCES plans(plan_id),
    primary_account_id INTEGER REFERENCES users(user_id) ON DELETE SET NULL,
    blocked_genres TEXT,
    favorite_genres TEXT,
    preferred_theme TEXT NOT NULL DEFAULT 'light',
    is_admin INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL,
    birth_date TEXT
);

CREATE INDEX IF NOT EXISTS idx_users_email ON users(email);

CREATE TABLE IF NOT EXISTS tracks (
    track_id INTEGER PRIMARY KEY AUTOINCREMENT,
    spotify_id TEXT,
    title TEXT NOT NULL,
    artist TEXT NOT NULL,
    duration_seconds INTEGER NOT NULL,
    genre TEXT NOT NULL,
    country TEXT,
    release_year INTEGER,
    cover_url TEXT,
    itunes_preview_url TEXT,
    explicit INTEGER NOT NULL DEFAULT 0,
    is_deleted INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_tracks_title ON tracks(title);
CREATE INDEX IF NOT EXISTS idx_tracks_artist ON tracks(artist);
CREATE INDEX IF NOT EXISTS idx_tracks_genre ON tracks(genre);
CREATE INDEX IF NOT EXISTS idx_tracks_spotify_id ON tracks(spotify_id);
CREATE INDEX IF NOT EXISTS idx_tracks_title_artist ON tracks(lower(title), lower(artist));

CREATE TABLE IF NOT EXISTS interactions (
    interaction_id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL REFERENCES users(user_id) ON DELETE CASCADE,
    track_id INTEGER NOT NULL REFERENCES tracks(track_id) ON DELETE CASCADE,
    action TEXT NOT NULL,
    created_at TEXT NOT NULL,
    source TEXT,
    jam_id INTEGER REFERENCES jams(jam_id) ON DELETE SET NULL,
    CONSTRAINT uq_interactions_user_track UNIQUE (user_id, track_id)
);

CREATE TABLE IF NOT EXISTS playlists (
    playlist_id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL REFERENCES users(user_id) ON DELETE CASCADE,
    name TEXT NOT NULL,
    description TEXT,
    spotify_playlist_id TEXT,
    is_exported INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL,
    max_duration_seconds INTEGER,
    deck_filters TEXT,
    cover_image_url TEXT,
    source_playlist_id INTEGER
);

CREATE TABLE IF NOT EXISTS playlist_images (
    playlist_id INTEGER PRIMARY KEY REFERENCES playlists(playlist_id) ON DELETE CASCADE,
    content_type TEXT NOT NULL,
    image_data BLOB NOT NULL,
    updated_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS playlist_tracks (
    playlist_track_id INTEGER PRIMARY KEY AUTOINCREMENT,
    playlist_id INTEGER NOT NULL REFERENCES playlists(playlist_id) ON DELETE CASCADE,
    track_id INTEGER NOT NULL REFERENCES tracks(track_id) ON DELETE CASCADE,
    added_at TEXT NOT NULL,
    CONSTRAINT uq_playlist_tracks_playlist_track UNIQUE (playlist_id, track_id)
);

CREATE TABLE IF NOT EXISTS jams (
    jam_id INTEGER PRIMARY KEY AUTOINCREMENT,
    host_user_id INTEGER NOT NULL REFERENCES users(user_id) ON DELETE CASCADE,
    room_name TEXT NOT NULL,
    room_code TEXT NOT NULL UNIQUE,
    is_active INTEGER NOT NULL DEFAULT 1,
    current_track_id INTEGER REFERENCES tracks(track_id) ON DELETE SET NULL,
    created_at TEXT NOT NULL,
    duration_minutes INTEGER NOT NULL DEFAULT 60,
    max_superlikes INTEGER NOT NULL DEFAULT 10,
    superlikes_used INTEGER NOT NULL DEFAULT 0,
    skip_votes_threshold INTEGER NOT NULL DEFAULT 3,
    accumulated_duration_seconds INTEGER NOT NULL DEFAULT 0,
    deck_source TEXT NOT NULL DEFAULT 'free',
    source_playlist_id INTEGER
);

CREATE TABLE IF NOT EXISTS jam_queue_items (
    jam_queue_id INTEGER PRIMARY KEY AUTOINCREMENT,
    jam_id INTEGER NOT NULL REFERENCES jams(jam_id) ON DELETE CASCADE,
    track_id INTEGER NOT NULL REFERENCES tracks(track_id) ON DELETE CASCADE,
    vote_points INTEGER NOT NULL DEFAULT 0,
    added_at TEXT NOT NULL,
    CONSTRAINT uq_jam_queue_items_jam_track UNIQUE (jam_id, track_id)
);

CREATE TABLE IF NOT EXISTS jam_participants (
    jam_id INTEGER NOT NULL REFERENCES jams(jam_id) ON DELETE CASCADE,
    user_id INTEGER NOT NULL REFERENCES users(user_id) ON DELETE CASCADE,
    joined_at TEXT NOT NULL,
    PRIMARY KEY (jam_id, user_id)
);

CREATE TABLE IF NOT EXISTS jam_skip_votes (
    jam_id INTEGER NOT NULL REFERENCES jams(jam_id) ON DELETE CASCADE,
    track_id INTEGER NOT NULL REFERENCES tracks(track_id) ON DELETE CASCADE,
    user_id INTEGER NOT NULL REFERENCES users(user_id) ON DELETE CASCADE,
    voted_at TEXT NOT NULL,
    PRIMARY KEY (jam_id, track_id, user_id)
);

CREATE TABLE IF NOT EXISTS reviews (
    review_id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL REFERENCES users(user_id) ON DELETE CASCADE,
    track_id INTEGER NOT NULL REFERENCES tracks(track_id) ON DELETE CASCADE,
    rating INTEGER NOT NULL,
    text TEXT,
    likes_count INTEGER NOT NULL DEFAULT 0,
    is_deleted INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_reviews_track_id ON reviews(track_id);
CREATE UNIQUE INDEX IF NOT EXISTS idx_reviews_active_user_track ON reviews(user_id, track_id) WHERE is_deleted = 0;

CREATE TABLE IF NOT EXISTS review_likes (
    review_id INTEGER NOT NULL REFERENCES reviews(review_id) ON DELETE CASCADE,
    user_id INTEGER NOT NULL REFERENCES users(user_id) ON DELETE CASCADE,
    created_at TEXT NOT NULL,
    PRIMARY KEY (review_id, user_id)
);

CREATE TABLE IF NOT EXISTS audit_logs (
    log_id INTEGER PRIMARY KEY AUTOINCREMENT,
    event TEXT NOT NULL,
    status TEXT NOT NULL,
    created_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS track_accesses (
    access_id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL REFERENCES users(user_id) ON DELETE CASCADE,
    track_id INTEGER NOT NULL REFERENCES tracks(track_id) ON DELETE CASCADE,
    source TEXT NOT NULL,
    accessed_at TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_track_accesses_user_time ON track_accesses(user_id, accessed_at DESC);
CREATE INDEX IF NOT EXISTS idx_track_accesses_track_id ON track_accesses(track_id);
CREATE INDEX IF NOT EXISTS idx_track_accesses_user_track ON track_accesses(user_id, track_id);

CREATE TABLE IF NOT EXISTS platform_cost_settings (
    settings_id INTEGER PRIMARY KEY CHECK (settings_id = 1),
    content_cost_per_track REAL NOT NULL DEFAULT 0.04,
    infrastructure_fixed_cost REAL NOT NULL DEFAULT 25.00,
    infrastructure_cost_per_user REAL NOT NULL DEFAULT 0.00,
    updated_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS firestore_usage_counters (
    metric_date TEXT PRIMARY KEY,
    reads_count INTEGER NOT NULL DEFAULT 0,
    writes_count INTEGER NOT NULL DEFAULT 0,
    deletes_count INTEGER NOT NULL DEFAULT 0,
    egress_bytes INTEGER NOT NULL DEFAULT 0,
    updated_at TEXT NOT NULL
);

-- Plans
